UPDATE public.business_category_templates t
SET
  group_id = source_rows.row->>'group_id',
  group_label = source_rows.row->>'group_label',
  category_label = source_rows.row->>'category_label',
  sort_order = (source_rows.row->>'sort_order')::integer,
  configuration = source_rows.row->'configuration',
  updated_at = now()
FROM source_rows
WHERE t.id = source_rows.row->>'id';

DO $$
DECLARE v_count integer;
BEGIN
  SELECT count(*) INTO v_count
  FROM public.business_category_templates
  WHERE configuration->>'source' = 'Digi Biashara Complete 150 Business Category Template Master Blueprint (109-page PDF)'
    AND configuration->>'template_version' = '2';
  IF v_count <> 150 THEN
    RAISE EXCEPTION 'Expected 150 complete version-2 category templates; found %.', v_count;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION branchpilot_private.seed_template_examples(p_business_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_template public.business_category_templates%rowtype;
  v_added integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_business_id::text, 481516));
  SELECT t.* INTO v_template
  FROM public.businesses b
  JOIN public.business_category_templates t ON t.id = b.business_category_template_id
  WHERE b.id = p_business_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'The business has no valid category template.'; END IF;

  INSERT INTO public.products (
    business_id, name, category, unit, cost_price, selling_price,
    quantity, low_stock_threshold, is_active, metadata
  )
  SELECT
    p_business_id,
    trim(e.item->>'name'),
    coalesce(nullif(trim(e.item->>'category'), ''), v_template.category_label),
    coalesce(nullif(trim(e.item->>'unit'), ''), 'piece'),
    0, 0, 0, 0, true,
    jsonb_build_object(
      'is_template_example', true,
      'editable_example', true,
      'template_id', v_template.id,
      'template_version', coalesce(v_template.configuration->>'template_version', '1'),
      'example_kind', coalesce(e.item->>'kind', 'product'),
      'price_status', 'needs_owner_input',
      'opening_stock_status', 'not_entered',
      'suggested_buying_price', null,
      'suggested_selling_price', null
    )
  FROM jsonb_array_elements(
    CASE WHEN jsonb_typeof(v_template.configuration->'product_examples') = 'array'
      THEN v_template.configuration->'product_examples' ELSE '[]'::jsonb END
  ) AS e(item)
  WHERE nullif(trim(e.item->>'name'), '') IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.products p
      WHERE p.business_id = p_business_id
        AND lower(trim(p.name)) = lower(trim(e.item->>'name'))
    );
  GET DIAGNOSTICS v_added = ROW_COUNT;
  RETURN v_added;
END;
$$;
REVOKE ALL ON FUNCTION branchpilot_private.seed_template_examples(uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.branchpilot_apply_category_template(p_business_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text := current_setting('request.jwt.claim.role', true);
BEGIN
  IF v_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL
       OR (
         NOT coalesce(public.is_platform_admin(), false)
         AND NOT EXISTS (
           SELECT 1 FROM public.business_memberships bm
           WHERE bm.business_id = p_business_id
             AND bm.user_id = v_uid
             AND bm.role = 'owner'
             AND bm.is_active = true
         )
       ) THEN
      RAISE EXCEPTION 'Only the platform administrator or business owner can apply this category template.';
    END IF;
  END IF;
  RETURN branchpilot_private.seed_template_examples(p_business_id);
END;
$$;
REVOKE ALL ON FUNCTION public.branchpilot_apply_category_template(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.branchpilot_apply_category_template(uuid) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.create_owner_business(
  p_name text,
  p_business_type text,
  p_activities jsonb,
  p_modules jsonb,
  p_templates jsonb,
  p_phone text DEFAULT NULL,
  p_email text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_count integer;
  v_business_id uuid;
  v_name text := trim(coalesce(p_name, ''));
  v_type text := trim(coalesce(p_business_type, ''));
  v_template record;
  v_modules jsonb;
  v_setup_templates jsonb;
  v_snapshot jsonb;
  v_seeded integer := 0;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Please sign in before adding a business.'; END IF;
  IF v_name = '' THEN RAISE EXCEPTION 'Enter a business name.'; END IF;
  IF length(v_name) > 120 THEN RAISE EXCEPTION 'Business name must be 120 characters or fewer.'; END IF;
  IF v_type = '' THEN RAISE EXCEPTION 'Choose a business category.'; END IF;
  IF jsonb_typeof(coalesce(p_activities, '[]'::jsonb)) <> 'array'
     OR jsonb_array_length(coalesce(p_activities, '[]'::jsonb)) < 1 THEN
    RAISE EXCEPTION 'Choose a business category.';
  END IF;
  IF jsonb_array_length(p_activities) > 30 THEN RAISE EXCEPTION 'Choose no more than 30 activities for one business.'; END IF;
  IF jsonb_typeof(coalesce(p_modules, '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_templates, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Invalid business setup profile.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.business_memberships bm
    WHERE bm.user_id = v_user AND bm.is_active = true AND bm.role = 'owner'
  ) THEN RAISE EXCEPTION 'Only a business owner can add another business.'; END IF;

  SELECT t.id,t.group_id,t.group_label,t.category_label,t.configuration INTO v_template
  FROM public.business_category_templates t
  WHERE t.is_active = true AND lower(trim(t.category_label)) = lower(v_type)
  ORDER BY t.sort_order LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'The selected category template is unavailable. Refresh and try again.'; END IF;

  v_modules := coalesce(v_template.configuration->'supported_modules',p_modules,'[]'::jsonb);
  v_setup_templates := coalesce(v_template.configuration->'features',p_templates,'[]'::jsonb);
  v_snapshot := jsonb_build_object(
    'template_id',v_template.id,'group_id',v_template.group_id,'group_label',v_template.group_label,
    'category_label',v_template.category_label,
    'template_version',coalesce((v_template.configuration->>'template_version')::integer,1),
    'configuration',coalesce(v_template.configuration,'{}'::jsonb),'applied_at',now()
  );

  PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text,0));
  SELECT count(DISTINCT bm.business_id) INTO v_count
  FROM public.business_memberships bm WHERE bm.user_id=v_user AND bm.role='owner';
  IF v_count>=5 THEN RAISE EXCEPTION 'You have reached the maximum of 5 businesses per owner.'; END IF;

  INSERT INTO public.businesses(
    name,business_type,business_activities,enabled_modules,setup_templates,
    business_category_template_id,business_template_snapshot,phone,email,status,created_by
  )
  VALUES(
    v_name,v_type,coalesce(p_activities,'[]'::jsonb),v_modules,v_setup_templates,
    v_template.id,v_snapshot,nullif(trim(coalesce(p_phone,'')),''),
    nullif(trim(coalesce(p_email,'')),''),'pending',v_user
  ) RETURNING id INTO v_business_id;

  INSERT INTO public.business_memberships(business_id,user_id,role,permissions,is_active)
  VALUES(v_business_id,v_user,'owner','{}'::jsonb,true);
  INSERT INTO public.business_subscriptions(business_id,monthly_fee,status,admin_notes)
  VALUES(v_business_id,0,'pending',
    'Owner-created business. Platform administrator must set pricing and confirm subscription before workspace access is enabled.');
  v_seeded := branchpilot_private.seed_template_examples(v_business_id);

  RETURN jsonb_build_object(
    'business_id',v_business_id,'status','pending','category_template_id',v_template.id,
    'businesses_used',v_count+1,'business_limit',5,'starter_examples_added',v_seeded
  );
END;
$function$;

UPDATE public.businesses b
SET
  enabled_modules = coalesce(t.configuration->'supported_modules','[]'::jsonb),
  setup_templates = coalesce(t.configuration->'features','[]'::jsonb),
  business_template_snapshot = coalesce(b.business_template_snapshot,'{}'::jsonb)
    || jsonb_build_object(
      'template_id',t.id,'group_id',t.group_id,'group_label',t.group_label,
      'category_label',t.category_label,
      'template_version',coalesce((t.configuration->>'template_version')::integer,1),
      'configuration',t.configuration,'applied_at',now(),
      'migration_note','Applied the completed BranchPilot category template. Existing business catalogue entries and transactions were preserved.'
    ),
  updated_at = now()
FROM public.business_category_templates t
WHERE b.business_category_template_id = t.id;

DO $$
DECLARE v_business record;
BEGIN
  FOR v_business IN SELECT id FROM public.businesses WHERE business_category_template_id IS NOT NULL
  LOOP
    PERFORM branchpilot_private.seed_template_examples(v_business.id);
  END LOOP;
END;
$$;
